import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from inlineLabels ----
type FruitPoint = { date: Date; fruit: string; value: number };

// Eight series over six months. Several deliberately cluster within a few units of each
// other so the label dodge has real collisions to resolve.
const MONTHLY: Array<[string, number[]]> = [
  ['Apples', [92, 104, 121, 138, 152, 171]],
  ['Bananas', [88, 96, 103, 118, 129, 144]],
  ['Cherries', [46, 58, 79, 112, 141, 158]],
  ['Durians', [63, 61, 66, 74, 83, 96]],
  ['Elderberries', [41, 44, 52, 61, 77, 88]],
  ['Figs', [58, 55, 63, 70, 81, 92]],
  ['Grapes', [110, 118, 112, 106, 99, 91]],
  ['Lychees', [34, 39, 48, 60, 72, 86]]
];

const months: Date[] = MONTHLY[0][1].map((_, i) => new Date(Date.UTC(2023, i, 1)));

const fruitSales: FruitPoint[] = MONTHLY.flatMap(([fruit, values]) =>
  values.map((value, i) => ({ date: months[i], fruit, value }))
);

/**
 * Long-form points, plus the columns they are labelled at. Every series carries one point
 * per column, in the same order, because the label dodge works column by column.
 */
export type Data = {
  points: { date: Date; fruit: string; value: number }[];
  columns: Date[];
};

const DEMO: Data = { points: fruitSales, columns: months };

const MARGIN = { top: 18, right: 104, bottom: 36, left: 20 };
const LABEL_GAP = 13;
const VALUE_SIZE = 11;
const NAME_DX = 16;

type Label = {
  key: string;
  x: number;
  y: number;
  text: string;
  color: string;
  anchor: 'middle' | 'start';
  weight: number;
};

// Pushes overlapping labels apart in one sorted pass, then recenters the column on its
// original mean so the block stays anchored to the data it came from.
function dodge(positions: number[], gap: number): number[] {
  const order = positions.map((_, i) => i).sort((a, b) => positions[a] - positions[b]);
  const out = new Array<number>(positions.length);
  let previous = -Infinity;
  for (const i of order) {
    out[i] = Math.max(positions[i], previous + gap);
    previous = out[i];
  }
  const shift = (d3.mean(positions) ?? 0) - (d3.mean(out) ?? 0);
  return out.map((v) => v + shift);
}

export default function InlineLabels({ data = DEMO, width }: { data?: Data; width: number }) {
  const height = Math.round(width * 0.55);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain([data.columns[0], data.columns[data.columns.length - 1]])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(() => {
    const [lo, hi] = d3.extent(data.points, (d) => d.value) as [number, number];
    return d3.scaleLinear().domain([lo - 8, hi + 8]).range([innerHeight, 0]);
  }, [data, innerHeight]);

  const series = useMemo(() => {
    const line = d3
      .line<Data['points'][number]>()
      .x((d) => x(d.date))
      .y((d) => y(d.value));
    return Array.from(d3.group(data.points, (d) => d.fruit), ([fruit, values]) => ({
      fruit,
      values,
      path: line(values) ?? ''
    }));
  }, [data, x, y]);

  const color = useMemo(
    () => d3.scaleOrdinal(series.map((s) => s.fruit), d3.schemeObservable10),
    [series]
  );

  // Every label position is resolved column by column, so a label never overlaps another
  // in the same month and the series name inherits its own dodged row.
  const labels: Label[] = useMemo(() => {
    const lastIndex = data.columns.length - 1;
    return data.columns.flatMap((date, column) => {
      const points = series.map((s) => s.values[column]);
      const dodged = dodge(points.map((p) => y(p.value)), LABEL_GAP);
      const cx = x(date);
      return points.flatMap((point, i) => {
        const row: Label = {
          key: `${point.fruit}-${column}`,
          x: cx,
          y: dodged[i],
          text: String(point.value),
          color: 'var(--text)',
          anchor: 'middle',
          weight: 400
        };
        if (column !== lastIndex) return [row];
        return [
          row,
          {
            key: `${point.fruit}-name`,
            x: cx + NAME_DX,
            y: dodged[i],
            text: point.fruit,
            color: color(point.fruit),
            anchor: 'start' as const,
            weight: 700
          }
        ];
      });
    });
  }, [data, series, x, y, color]);

  const xTicks: Tick[] = useMemo(
    () => data.columns.map((d) => ({ value: d3.utcFormat('%b')(d), offset: x(d) })),
    [data, x]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Multi-line chart of monthly fruit sales with values labelled directly on each line in place of a y-axis"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {series.map((s) => (
          <path
            key={s.fruit}
            d={s.path}
            fill="none"
            stroke={color(s.fruit)}
            strokeWidth={1.5}
            strokeLinejoin="round"
            strokeLinecap="round"
          />
        ))}
        {/* Halo pass: every label is painted once as a thick panel-coloured stroke so the
            text pass below reads cleanly wherever it crosses a line. */}
        {labels.map((l) => (
          <text
            key={`halo-${l.key}`}
            x={l.x}
            y={l.y}
            dy="0.35em"
            textAnchor={l.anchor}
            fontSize={VALUE_SIZE}
            fontWeight={l.weight}
            fill="none"
            stroke="var(--panel)"
            strokeWidth={5}
            strokeLinejoin="round"
            strokeLinecap="round"
          >
            {l.text}
          </text>
        ))}
        {labels.map((l) => (
          <text
            key={l.key}
            x={l.x}
            y={l.y}
            dy="0.35em"
            textAnchor={l.anchor}
            fontSize={VALUE_SIZE}
            fontWeight={l.weight}
            fill={l.color}
          >
            {l.text}
          </text>
        ))}
      </g>
    </svg>
  );
}
